begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at)values('f1250000-0000-0000-0000-000000000001','flow-owner@test.invalid',now()),('f1250000-0000-0000-0000-000000000002','flow-other@test.invalid',now()),('f1250000-0000-0000-0000-000000000003','flow-pending@test.invalid',null);
