insert into public.properties(id,tenant_id,name,property_type)values('f1252000-0000-0000-0000-000000000001','f1251000-0000-0000-0000-000000000001','Old Hotel','hotel'),('f1252000-0000-0000-0000-000000000002','f1251000-0000-0000-0000-000000000001','New Hotel','hotel'),('f1252000-0000-0000-0000-000000000003','f1251000-0000-0000-0000-000000000002','Other Hotel','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role)values('f1251000-0000-0000-0000-000000000001','f1250000-0000-0000-0000-000000000001','owner'),('f1251000-0000-0000-0000-000000000002','f1250000-0000-0000-0000-000000000002','owner');
insert into public.accommodation_types(id,tenant_id,property_id,name,max_occupancy,base_rate)values('f1253000-0000-0000-0000-000000000001','f1251000-0000-0000-0000-000000000001','f1252000-0000-0000-0000-000000000001','QA Standard',2,100);
insert into public.accommodation_units(id,tenant_id,property_id,type_id,name,housekeeping_status)select('f1254000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'f1251000-0000-0000-0000-000000000001','f1252000-0000-0000-0000-000000000001','f1253000-0000-0000-0000-000000000001','Room '||lpad(n::text,2,'0'),'dirty'from generate_series(1,24)n;
insert into public.property_settings(property_id,tenant_id,cleaning_checklist)values('f1252000-0000-0000-0000-000000000001','f1251000-0000-0000-0000-000000000001','["Inspect room"]')on conflict(property_id)do update set cleaning_checklist=excluded.cleaning_checklist;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1250000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(jsonb_array_length(public.inventory_room_selection('f1252000-0000-0000-0000-000000000001')),24,'Select all matching rooms spans the twenty-row page boundary');
select is(jsonb_array_length(public.inventory_room_selection('f1252000-0000-0000-0000-000000000001','{"q":"Room 01"}')),1,'Bulk selection respects current search filters');
select set_config('test.items',public.inventory_room_selection('f1252000-0000-0000-0000-000000000001')::text,true);
select is((public.inventory_bulk_rooms('f1252000-0000-0000-0000-000000000001','f1255000-0000-0000-0000-000000000001',current_setting('test.items')::jsonb,'clean')->>'updated')::integer,24,'One inspected bulk action marks all selected rooms clean');
select is((select count(*)::integer from public.accommodation_units where property_id='f1252000-0000-0000-0000-000000000001'and housekeeping_status='clean'),24,'All selected room cleanliness values are persisted');
select is((public.inventory_bulk_rooms('f1252000-0000-0000-0000-000000000001','f1255000-0000-0000-0000-000000000001',current_setting('test.items')::jsonb,'clean')->>'updated')::integer,24,'A replay returns the same result without duplicating room actions');
select is((select count(*)::integer from public.inventory_events where property_id='f1252000-0000-0000-0000-000000000001'and action='bulk_clean'),24,'Bulk replay creates no duplicate audits');
select is((public.inventory_bulk_rooms('f1252000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.items')::jsonb,'clean')->>'updated')::integer,0,'Stale room versions produce per-room failures');
select throws_ok($$select public.inventory_bulk_rooms('f1252000-0000-0000-0000-000000000001','f1255000-0000-0000-0000-000000000001',current_setting('test.items')::jsonb,'start')$$,'22023',null,'A command cannot be reused for another action');
select set_config('test.assign',(select jsonb_agg(x)from(select x from jsonb_array_elements(public.inventory_room_selection('f1252000-0000-0000-0000-000000000001'))x limit 2)y)::text,true);
select is((public.inventory_bulk_rooms('f1252000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.assign')::jsonb,'assign','f1250000-0000-0000-0000-000000000001')->>'updated')::integer,2,'Selected rooms can be assigned to an eligible housekeeping teammate');
select is((select count(*)::integer from public.tasks where property_id='f1252000-0000-0000-0000-000000000001'and assignee_id='f1250000-0000-0000-0000-000000000001'),2,'Assignment creates two separate room tasks');
select is((public.inventory_bulk_rooms('f1252000-0000-0000-0000-000000000001',gen_random_uuid(),public.inventory_room_selection('f1252000-0000-0000-0000-000000000001','{"state":"dirty"}'),'clean')->>'updated')::integer,0,'Bulk clean cannot bypass unfinished room checklists');
select is((public.inventory_bulk_rooms('f1252000-0000-0000-0000-000000000001',gen_random_uuid(),public.inventory_room_selection('f1252000-0000-0000-0000-000000000001','{"state":"dirty"}'),'start')->>'updated')::integer,2,'Bulk start reuses the existing cleaning tasks');
select is((select count(*)::integer from public.tasks where property_id='f1252000-0000-0000-0000-000000000001'),2,'Start does not duplicate assigned housekeeping tasks');
select throws_ok($$select public.inventory_bulk_rooms('f1252000-0000-0000-0000-000000000001',gen_random_uuid(),current_setting('test.assign')::jsonb,'assign','f1250000-0000-0000-0000-000000000002')$$,'22023',null,'Cannot assign rooms to another tenant’s teammate');
reset role;
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('f1256000-0000-0000-0000-000000000001','f1251000-0000-0000-0000-000000000001','f1252000-0000-0000-0000-000000000001','125123450001','125123450002','+919000001125','managed:f1252000-0000-0000-0000-000000000001');
insert into private.whatsapp_credentials values('f1252000-0000-0000-0000-000000000001','managed:f1252000-0000-0000-0000-000000000001',repeat('a',80),now());
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id)values('f1257000-0000-0000-0000-000000000001','f1251000-0000-0000-0000-000000000001','f1252000-0000-0000-0000-000000000001','f1256000-0000-0000-0000-000000000001','919000000125');
insert into public.messages(id,tenant_id,property_id,conversation_id,direction,type,body,status)values('f1258000-0000-0000-0000-000000000001','f1251000-0000-0000-0000-000000000001','f1252000-0000-0000-0000-000000000001','f1257000-0000-0000-0000-000000000001','out','text','Synthetic message','sending');
set local role authenticated;
select is(jsonb_array_length(public.whatsapp_transfer_choices('f1252000-0000-0000-0000-000000000002')),1,'New hotel shows a movable connection administered by this owner');
select throws_ok($$select public.whatsapp_transfer_context('f1252000-0000-0000-0000-000000000003','f1252000-0000-0000-0000-000000000001')$$,'42501',null,'Transfer details require access to both hotels');
reset role;set local role service_role;
select throws_ok($$select public.whatsapp_transfer_commit('f1252000-0000-0000-0000-000000000002','f1252000-0000-0000-0000-000000000001','f1250000-0000-0000-0000-000000000002','f1256000-0000-0000-0000-000000000001',repeat('b',80))$$,'42501',null,'Backend rechecks the actor’s access to both hotels');
select throws_ok($$select public.whatsapp_transfer_commit('f1252000-0000-0000-0000-000000000002','f1252000-0000-0000-0000-000000000001','f1250000-0000-0000-0000-000000000001','f1256000-0000-0000-0000-000000000001',repeat('b',80))$$,'22023',null,'In-flight sends block transfer');
reset role;
update public.messages set status='queued'where id='f1258000-0000-0000-0000-000000000001';
update public.whatsapp_default_setup set lease=gen_random_uuid(),locked_at=now()where property_id='f1252000-0000-0000-0000-000000000001';
set local role service_role;
select throws_ok($$select public.whatsapp_transfer_commit('f1252000-0000-0000-0000-000000000002','f1252000-0000-0000-0000-000000000001','f1250000-0000-0000-0000-000000000001','f1256000-0000-0000-0000-000000000001',repeat('b',80))$$,'22023',null,'An active template setup job blocks transfer');
reset role;
update public.whatsapp_default_setup set lease=null,locked_at=null where property_id='f1252000-0000-0000-0000-000000000001';
set local role service_role;
select lives_ok($$select public.whatsapp_transfer_commit('f1252000-0000-0000-0000-000000000002','f1252000-0000-0000-0000-000000000001','f1250000-0000-0000-0000-000000000001','f1256000-0000-0000-0000-000000000001',repeat('b',80))$$,'Managed sender transfers atomically after backend verification');
reset role;
select is((select status from public.whatsapp_connections where property_id='f1252000-0000-0000-0000-000000000001'),'disabled','Old hotel is disconnected');
select is((select status from public.whatsapp_connections where property_id='f1252000-0000-0000-0000-000000000002'),'active','New hotel becomes active');
select is((select count(*)::integer from public.whatsapp_connections where phone_number_id='125123450001'and status='active'),1,'A phone routes to exactly one active hotel');
select is((select count(*)::integer from public.conversations where property_id='f1252000-0000-0000-0000-000000000002'),0,'Old conversations are not copied into the new hotel');
select is((select count(*)::integer from public.conversations where property_id='f1252000-0000-0000-0000-000000000001'),1,'Old hotel retains its conversation history');
select is((select status from public.messages where id='f1258000-0000-0000-0000-000000000001'),'failed','Old queued messages cannot send after transfer');
select is((select count(*)::integer from private.whatsapp_credentials where property_id='f1252000-0000-0000-0000-000000000001'),0,'Old hotel loses its credentials');
select is((select ciphertext from private.whatsapp_credentials where property_id='f1252000-0000-0000-0000-000000000002'),repeat('b',80),'New hotel receives separately sealed credentials');
select throws_ok($$insert into public.whatsapp_connections(tenant_id,property_id,phone_number_id,waba_id,credentials_ref)values('f1251000-0000-0000-0000-000000000002','f1252000-0000-0000-0000-000000000003','125123450001','125123450002','synthetic')$$,'23505',null,'The same phone cannot be active in two hotels');
set local role authenticated;
select public.whatsapp_setup_disconnect('f1252000-0000-0000-0000-000000000002');
reset role;
insert into public.properties(id,tenant_id,name,property_type)values('f1252000-0000-0000-0000-000000000004','f1251000-0000-0000-0000-000000000001','Fresh hotel','hotel');
set local role authenticated;
select public.whatsapp_setup_begin_v2('f1252000-0000-0000-0000-000000000004','cloud_api')as reconnect_session \gset
reset role;set local role service_role;
select public.whatsapp_setup_claim_v2(:'reconnect_session','f1250000-0000-0000-0000-000000000001');
select lives_ok(format('select public.whatsapp_setup_commit(%L,%L,%L,%L,%L,%L)',:'reconnect_session','f1250000-0000-0000-0000-000000000001','125123450001','125123450002','+919000001125',repeat('c',80)),'Fresh verified Meta signup can reuse a disconnected number despite historical connections');
reset role;
select is((select count(*)::integer from public.whatsapp_connections where phone_number_id='125123450001'and status='active'),1,'Reconnect still leaves exactly one active sender');
set local role service_role;
select is(public.signup_account_check('FLOW-OWNER@test.invalid',repeat('a',64)),'exists','Signup recognizes an existing confirmed email case-insensitively');
select is(public.signup_account_check('flow-pending@test.invalid',repeat('a',64)),'pending','Unconfirmed accounts also cannot be recreated');
select is(public.signup_account_check('new-flow@test.invalid',repeat('a',64)),'new','A new email can proceed to confirmation');
select public.signup_account_check('limited-flow@test.invalid',repeat('c',64))from generate_series(1,6);
select is(public.signup_account_check('limited-flow@test.invalid',repeat('c',64)),'limited','Duplicate lookup is rate limited');
reset role;set local role anon;
select throws_ok($$select public.signup_account_check('flow-owner@test.invalid',repeat('a',64))$$,'42501',null,'The auth account lookup is not available to anonymous RPC callers');
select throws_ok($$select public.whatsapp_transfer_commit('f1252000-0000-0000-0000-000000000002','f1252000-0000-0000-0000-000000000001','f1250000-0000-0000-0000-000000000001','f1256000-0000-0000-0000-000000000001',repeat('b',80))$$,'42501',null,'Clients cannot supply transfer ciphertext or impersonate another actor');
select *from finish();rollback;
